                 info.setSize(srcFile.length()/1024);
                 logger.info("æä»¶å¤§å°:" + info.getSize() + " (KB)");
                 try {
                    info.setCode(MD5Util.MD5(new FileInputStream(srcFile)));
                } catch (FileNotFoundException e) {
                    logger.error(e);
                    e.printStackTrace();
                }
                 logger.info("æä»¶MD5æ ¡éªç :" + info.getCode());
                 info.setCreateTime(new Date());
                 String newFileName = info.getId() + info.getExt();
                 info.setPath(destFolder + newFileName);
                 logger.info("å­å¨ç¸å¯¹è·¯å¾:" + info.getPath());
                 logger.info("å­å¨ç»å¯¹è·¯å¾:" + destPath + newFileName);
                 if(IOUtil.copyFile(srcFile, new File(destPath + newFileName), true)){
                        BeanUtils.copyProperties(info, data);
                        if(isAdded) this.pictureDao.save(data);
                        logger.info("å¾çå·²æåç§»å¨å°å¾çåºï¼");
                 }else{
                     logger.error("å¾çç§»å¨å°å¾çåºå¤±è´¥ï¼");
                 }
                 logger.info("ç§»å¨å¾çå®æï¼");
