public class GatewayMoudleDispatcher implements IDispatcher<Fenrisulfr.RpcPacket>
{
    private static final Logger log = LoggerFactory.getLogger(GatewayMoudleDispatcher.class);

    @Inject
    private GatewayAllMoudleService gatewayAllMoudleService;

    @Override
    public void diapatch(Channel channel, Fenrisulfr.RpcPacket packet)
    {
        try
        {
            int opcode = packet.getOpcode();
            int moudle = DispatcherHelper.moudleType(opcode);
