  public static void main(String[] args) {

    boolean primo;
    int i = 1; 

    while (i < 100){
        i++; 
        primo = true;

        for (int b = 2; b < i; b++){

            if ((i % b) == 0){
                primo = false;
            }
        }

        if (primo){
            System.out.println(i + "");
