public class Solution {
    public int maximumGap_1(int[] num) {
        Arrays.sort(num);
        int res = 0;
        for (int i = 1; i < num.length; ++i) {
            res = Math.max(res, num[i] - num[i - 1]);
        }
        return res;
    }
    class node {
        public int low;
        public int high;
        public node() {
            low = -1;
            high = -1;
        }
    }
    public int maximumGap_2(int[] num) {
        int n = num.length;
        if (n < 2) return 0;
        int minVal = num[0], maxVal = num[0];
        for (int i = 1; i < n; ++i) {
            minVal = Math.min(minVal, num[i]);
            maxVal = Math.max(maxVal, num[i]);
        }
        node[] pool = new node[n+2];
        for (int i = 0; i < n+2; ++i) pool[i] = new node();
        for (int i = 0; i < n; ++i) {
            int idx =(int)(Long.valueOf(num[i] - minVal)* Long.valueOf(n + 1) / Long.valueOf(maxVal + 1 - minVal));
            if (pool[idx].low == -1) {
                pool[idx].low = pool[idx].high = num[i];
            } else {
                pool[idx].low = Math.min(pool[idx].low, num[i]);
                pool[idx].high = Math.max(pool[idx].high, num[i]);
            }
        }
        int pre = pool[0].high;
        int res = 0;
        for (int i = 1; i < n + 2; ++i) {
            if (pool[i].low != -1) {
                res = Math.max(res, pool[i].low - pre);
                pre = pool[i].high;
            }
        }
        return res;
    }
},31

public class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int N = gas.length;
        int res = 0, min = gas[0] - cost[0], sum = min;
        for (int i = 1; i < N; ++i) {
            sum += gas[i] - cost[i];
            if (sum < min) {
                min = sum;
                res = i;
            }
        }
        return sum >= 0 ? (res + 1) % N : -1;
    }
},31

public class Solution {
    public void reorderList_1(ListNode head) {
        ListNode slow = head, fast = head;
        if (head == null || head.next == null) return;
        while (fast.next != null && fast.next.next != null) {
            fast = fast.next.next;
            slow = slow.next;
        }
        fast = slow.next;
        slow.next = null;
        slow = head;
        ListNode pre = null;
        while (fast != null) {
            ListNode next = fast.next;
            fast.next = pre;
            pre = fast;
            fast = next;
        }
        fast = pre;
        while (fast != null) {
            ListNode fastnext = fast.next;
            fast.next = slow.next;
            slow.next = fast;
            fast = fastnext;
            slow = slow.next.next;
        }
    }
    public void reorderList_2(ListNode head) {
        ListNode slow = head, fast = head;
        if (head == null || head.next == null) return;
        while (fast.next != null && fast.next.next != null) {
            fast = fast.next.next;
            slow = slow.next;
        }
        fast = slow.next;
        while (fast.next != null) {
            ListNode move = fast.next;
            fast.next = move.next;
            move.next = slow.next;
            slow.next = move;
        }
        fast = slow.next;
        slow.next = null;
        slow = head;
        while (fast != null) {
            ListNode fastnext = fast.next;
            fast.next = slow.next;
            slow.next = fast;
            fast = fastnext;
            slow = slow.next.next;
        }
    }
