public class Solution {
    public boolean isScramble_1(String s1, String s2) {
        if (s1.compareTo(s2) == 0) return true;
        if (s1.length() != s2.length()) return false;
        return isScrambleRe(s1, s2);
    }
    public boolean isScrambleRe(String s1, String s2) {
        if (hasSameLetters(s1, s2) == false) return false;
        int len = s1.length();
        if (len == 0 || len == 1) return true;
        for (int i = 1; i < len; ++i) {
            if (isScrambleRe(s1.substring(0,i), s2.substring(0,i)) 
                && isScrambleRe(s1.substring(i), s2.substring(i)) 
                || isScrambleRe(s1.substring(0,i), s2.substring(len-i)) 
                && isScrambleRe(s1.substring(i), s2.substring(0,len-i))) {
                    return true;
                }
        }
        return false;
    }
    public boolean hasSameLetters(String s1, String s2) {
        if (s1.compareTo(s2) == 0) return true;
        if (s1.length() != s2.length()) return false;
        int[] count = new int[256];
        for (int i = 0; i < s1.length(); ++i) count[(int)s1.charAt(i)]++;
        for (int i = 0; i < s2.length(); ++i) count[(int)s2.charAt(i)]--;
        for (int i = 0; i < 256; ++i)
            if (count[i] != 0) return false;
        return true;
    }
    public boolean isScramble(String s1, String s2) {
        if (s1.compareTo(s2) == 0) return true;
        if (s1.length() != s2.length()) return false;
        int N = s1.length();
        boolean[][][] dp = new boolean[N+1][N][N];
        for (int k = 1; k <= N; ++k) {
            for (int i = 0; i <= N - k; ++i) {
                for (int j = 0; j <= N - k; ++j) {
                    dp[k][i][j] = false;
                    if (k == 1) dp[1][i][j] = (s1.charAt(i) == s2.charAt(j));
                    for (int p = 1; p < k && !dp[k][i][j]; ++p) {
                        if (dp[p][i][j] && dp[k-p][i+p][j+p] || dp[p][i][j+k-p] && dp[k-p][i+p][j])
                            dp[k][i][j] = true;
                    }
                }
            }
        }
        return dp[N][0][0];
    }
},31

public class Solution {
    public List<List<Integer>> combinationSum(int[] candidates, int target) {
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        Arrays.sort(candidates);
        ArrayList<Integer> path = new ArrayList<Integer>();
        combinationSumRe(candidates, target, 0, path, res);
        return res;
    }
    void combinationSumRe(int[] candidates, int target, int start, ArrayList<Integer> path, List<List<Integer>> res) {
        if (target == 0) {
            ArrayList<Integer> p = new ArrayList<Integer>(path);
            res.add(p);
            return;
        }
        for (int i = start; i < candidates.length && target >= candidates[i]; ++i) {
            path.add(candidates[i]);
            combinationSumRe(candidates, target-candidates[i], i, path, res);
            path.remove(path.size() - 1);
        }
    }
},31

public class Solution {
    public String minWindow(String S, String T) {
        int N = S.length(), M = T.length();
        if (N < M) return new String("");
        int[] need = new int[256];
        int[] find = new int[256];
        for (int i = 0; i < M; ++i)
            need[T.charAt(i)]++;

        int count = 0, resStart = -1, resEnd = N;
        for (int start = 0, end = 0; end < N; ++end)
        {
            if (need[S.charAt(end)] == 0)
                continue;
            if (find[S.charAt(end)] < need[S.charAt(end)])
                count++;
            find[S.charAt(end)]++;
            if (count != M) continue;
            for (; start < end; ++start) {
                if (need[S.charAt(start)] == 0) continue;
                if (find[S.charAt(start)] <= need[S.charAt(start)]) break;
                find[S.charAt(start)]--;
            }
            if (end - start < resEnd - resStart) {
                resStart = start;
                resEnd = end;
            }
        }
        return (resStart == -1) ? new String("") : S.substring(resStart, resEnd + 1); 
    }
},31

