class OperatorDemo2 {
    public static void main(String[] args) {
        int a = 10;
        int b = 20;
        int c = 30;

        System.out.println(a>b & a>c); System.out.println(a>b & a<c); System.out.println(a<b & a>c); System.out.println(a<b & a<c); System.out.println("--------");

        System.out.println(a>b && a>c); System.out.println(a>b && a<c); System.out.println(a<b && a>c); System.out.println(a<b && a<c); System.out.println("--------");

        System.out.println(a>b | a>c); System.out.println(a>b | a<c); System.out.println(a<b | a>c); System.out.println(a<b | a<c); System.out.println("--------");

        System.out.println(a>b || a>c); System.out.println(a>b || a<c); System.out.println(a<b || a>c); System.out.println(a<b || a<c); System.out.println("--------");

        int x = 3;
        int y = 4;
        System.out.println((x++)>3 && (y++)>4);
        System.out.println(x);System.out.println(y);}
}
